		       || TREE_CODE (TYPE_NAME (t1)) == IDENTIFIER_NODE);
  gcc_checking_assert (!TYPE_NAME (t2)
		       || TREE_CODE (TYPE_NAME (t2)) == IDENTIFIER_NODE);

