comptypes_internal (const_tree type1, const_tree type2,
		    struct comptypes_data *data)
{
  const_tree t1 = type1;
  const_tree t2 = type2;

  /* Suppress errors caused by previously reported errors.  */

  if (t1 == t2 || !t1 || !t2
      || TREE_CODE (t1) == ERROR_MARK || TREE_CODE (t2) == ERROR_MARK)
    return true;

